mapper.select:
SELECT
    (SELECT COALESCE(SUM(total_price), 0)
     FROM erp_purchase_in
     WHERE in_time >= #{beginTime}

           AND in_time < #{endTime}


           AND tenant_id = ${@com.group.antian.framework.tenant.core.context.TenantContextHolder@getTenantId()}

       AND deleted = 0
       AND status = 20) -
    (SELECT COALESCE(SUM(total_price), 0)
        FROM erp_purchase_return
        WHERE return_time >= #{beginTime}

            AND return_time < #{endTime}


            AND tenant_id = ${@com.group.antian.framework.tenant.core.context.TenantContextHolder@getTenantId()}

        AND deleted = 0
        AND status = 20)
${@com.group.antian.framework.mybatis.core.util.SqlDialectUtils@fromDual()}
